public class OrderService
{
    public event EventHandler<OrderPaidEventArgs>? Paid;
    protected virtual void OnPaid(Order order) =>
        Paid?.Invoke(this, new OrderPaidEventArgs(order));
}

const emitter = new EventEmitter();

function mount() {
  const handler = () => console.log('tick');
  emitter.on('tick', handler);
  // BUG: never emitter.off('tick', handler) on unmount
}

for (let i = 0; i < 100; i++) mount();
